// Regenerates src/chain/abi.ts from the forge artifact. Run after `forge build` changes the contract:
//   node scripts/gen-abi.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../../", import.meta.url));
const artifact = JSON.parse(readFileSync(root + "out/TipEscrow.sol/TipEscrow.json", "utf8"));
const abi = artifact.abi.filter((x) => x.type !== "constructor");

const out = `// GENERATED by scripts/gen-abi.mjs from out/TipEscrow.sol/TipEscrow.json (forge build of src/TipEscrow.sol).
// Do not edit by hand. The deployed address and network live in src/chain/config.ts (from deployment.json).
export const tipEscrowAbi = ${JSON.stringify(abi, null, 2)} as const;

/** DogeOS L1 gas price oracle (a Scroll L1GasPriceOracle), pre-deployed. FEES.md section 3, scripts/fee-check.cjs. */
export const l1GasOracleAbi = [
  { type: "function", name: "getL1Fee", stateMutability: "view", inputs: [{ name: "data", type: "bytes" }], outputs: [{ name: "", type: "uint256" }] },
] as const;
`;
writeFileSync(fileURLToPath(new URL("../src/chain/abi.ts", import.meta.url)), out);
console.log(`wrote src/chain/abi.ts (${abi.length} entries)`);
